def apply_integration_runtime_endpoints(
    endpoints: AvailableEndpoints, project_root: str | Path
) -> None:
    """Replace the keys this module owns on ``endpoints`` from ``integrations.yml``.

    Mutates ``endpoints`` in place. Each owned key is set from
    ``integrations.yml`` or cleared when that file omits it. Mantle startup
    does not read ``endpoints.yml``, so this receives an empty object.

    Args:
        endpoints: Endpoint object to update. Startup passes an empty one.
        project_root: Directory expected to contain ``integrations.yml``.

    Raises:
        RasaException: If ``integrations.yml`` exists but its root is not a
            mapping, or if an owned section in that file is invalid.
    """
    event_broker = load_integration_event_broker(project_root)
    _overlay_endpoint(
        endpoints,
        EVENT_BROKER_KEY,
        event_broker.as_endpoint_config() if event_broker is not None else None,
    )
    timer_store = load_integration_timer_store(project_root)
    _overlay_endpoint(
        endpoints,
        TIMER_STORE_KEY,
        timer_store.as_endpoint_config() if timer_store is not None else None,
    )
    tracker_store = load_integration_tracker_store(project_root)
    _overlay_endpoint(
        endpoints,
        TRACKER_STORE_KEY,
        tracker_store.as_endpoint_config() if tracker_store is not None else None,
    )
    lock_store = load_integration_lock_store(project_root)
    _overlay_endpoint(
        endpoints,
        LOCK_STORE_KEY,
        lock_store.as_endpoint_config() if lock_store is not None else None,
    )
    model_server = load_integration_model_server(project_root)
    _overlay_endpoint(
        endpoints,
        RASA_MODEL_SERVER_KEY,
        model_server.as_endpoint_config() if model_server is not None else None,
        attribute=MODEL_ENDPOINT_ATTRIBUTE,
    )
    _overlay_endpoint(
        endpoints,
        RECORDINGS_KEY,
        load_integration_recordings(project_root),
    )


def _overlay_endpoint(
    endpoints: AvailableEndpoints,
    key: str,
    loaded: Optional[Union[EndpointConfig, RecordingConfig]],
    *,
    attribute: Optional[str] = None,
) -> None:
    """Set one owned key from ``integrations.yml``.

    ``attribute`` is the ``AvailableEndpoints`` field when it differs from the
    integrations key (``rasa_model_server:`` is stored as ``model``).
    """
    setattr(endpoints, attribute or key, loaded)


def _validate_redis_timer_store(raw_timer_store: Mapping[str, Any]) -> None:
    """Check a Redis timer store against the config the factory builds from.

    Validates only. Constructing the store would open a Redis connection.
    """
    # Imported lazily: the Redis client is unused for in-memory and custom stores.
    from rasa.core.timer_stores.redis_timer_store import RedisSessionTimerStoreConfig

    try:
        RedisSessionTimerStoreConfig.model_validate(dict(raw_timer_store))
    except ValidationError as error:
        problems = "; ".join(
            f"'{'.'.join(str(part) for part in issue['loc']) or TIMER_STORE_KEY}': "
            f"{issue['msg']}"
            for issue in error.errors(include_input=False)
        )
        raise ValueError(problems) from error
    except RasaException as error:
        raise ValueError(str(error)) from error
